create extension if not exists pgcrypto;
create table if not exists public.accounts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,firm text default '',account_type text default 'Personal',initial_balance numeric(14,2) not null default 5000 check(initial_balance>0),daily_drawdown_pct numeric(6,2) default 0,max_drawdown_pct numeric(6,2) default 0,floating_loss_cap numeric(14,2),reward_split_pct numeric(6,2) default 0,qualifying_days integer default 0,daily_qualifying_profit numeric(14,2) default 0,consistency_pct numeric(6,2) default 0,personal_daily_stop numeric(14,2) default 0,created_at timestamptz default now());
create table if not exists public.trades(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,account_id uuid not null references public.accounts(id) on delete cascade,traded_at timestamptz not null default now(),symbol text not null,side text not null check(side in('BUY','SELL')),lot_size numeric(14,4) not null,gross_pnl numeric(14,2) not null,costs numeric(14,2) default 0,entry_price numeric(18,8),exit_price numeric(18,8),stop_loss numeric(18,8),take_profit numeric(18,8),result_type text not null default 'CUSTOM' check(result_type in('SL','TP','CUSTOM')),setup text,session text,emotion text,grade text,risk_amount numeric(14,2),r_multiple numeric(10,3),notes text,screenshot_path text,created_at timestamptz default now());
create table if not exists public.events(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,currency text default '',impact text default 'Medium',event_at timestamptz not null,created_at timestamptz default now());
alter table public.accounts enable row level security;alter table public.trades enable row level security;alter table public.events enable row level security;
drop policy if exists accounts_owner on public.accounts;create policy accounts_owner on public.accounts for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists trades_owner on public.trades;create policy trades_owner on public.trades for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists events_owner on public.events;create policy events_owner on public.events for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
insert into storage.buckets(id,name,public) values('trade-screenshots','trade-screenshots',false) on conflict(id) do nothing;
drop policy if exists screenshot_read_owner on storage.objects;create policy screenshot_read_owner on storage.objects for select to authenticated using(bucket_id='trade-screenshots' and (storage.foldername(name))[1]=auth.uid()::text);
drop policy if exists screenshot_insert_owner on storage.objects;create policy screenshot_insert_owner on storage.objects for insert to authenticated with check(bucket_id='trade-screenshots' and (storage.foldername(name))[1]=auth.uid()::text);
drop policy if exists screenshot_delete_owner on storage.objects;create policy screenshot_delete_owner on storage.objects for delete to authenticated using(bucket_id='trade-screenshots' and (storage.foldername(name))[1]=auth.uid()::text);
create index if not exists trades_account_date on public.trades(account_id,traded_at desc);create index if not exists events_owner_date on public.events(user_id,event_at);